function openDb(){if(!('indexedDB'in window))return Promise.reject(Error('此浏览器不支持 IndexedDB'));if(dbReady)return dbReady;dbReady=new Promise((resolve,reject)=>{const request=indexedDB.open(DB_NAME,DB_VERSION);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(DB_STORE))db.createObjectStore(DB_STORE,{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});return dbReady;}
async function persistProject(){if(!state.name&&!state.files.length)return;try{const db=await openDb(),data=portableSnapshot(payload());data.id=state.id||(state.id=uid('project'));data.project.id=state.id;data.project.updatedAt=new Date().toISOString();await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).put(data);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});$('project-save-state').textContent='已自动保存到本机';}catch(error){$('project-save-state').textContent=`本机保存失败：${error.message}；请保存 .lsvproj 备份`;}}
