 document.querySelectorAll('.project-check').forEach(cb=>cb.onchange=()=>{const f=state.files.find(x=>x.id===cb.dataset.id);if(f)f.selected=cb.checked;updateOrigin();});
 document.querySelectorAll('.save-sample-name').forEach(button=>button.onclick=()=>{const input=button.previousElementSibling,value=input.value.trim()||'未分组';state.files.filter(x=>x.sampleId===input.dataset.sampleId).forEach(x=>x.sampleName=value);renderProject();changed();});
 document.querySelectorAll('.sample-label').forEach(input=>input.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();input.nextElementSibling.click();}});
 document.querySelectorAll('.save-group-name').forEach(button=>button.onclick=()=>{const input=button.previousElementSibling,value=input.value.trim()||'测试 1',siblings=state.files.filter(x=>x.sampleId===input.dataset.sampleId&&x.testGroup===value&&x.testGroupId!==input.dataset.groupId),target=siblings[0]?.testGroupId||input.dataset.groupId;state.files.filter(x=>x.sampleId===input.dataset.sampleId&&x.testGroupId===input.dataset.groupId).forEach(x=>{x.testGroup=value;x.testGroupId=target;});renderProject();changed();});
 document.querySelectorAll('.group-label').forEach(input=>input.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();input.nextElementSibling.click();}});
 document.querySelectorAll('.save-file-name').forEach(button=>button.onclick=()=>{const input=button.previousElementSibling,f=state.files.find(x=>x.id===input.dataset.id);if(f){f.testLabel=input.value.trim()||f.originalName;renderProject();changed();}});
