$('project-search').addEventListener('input',renderProject);
function updateOrigin(){$('project-origin').disabled=!state.files.some(f=>!f.deletedAt&&f.kind==='lsv'&&f.selected!==false&&state.records[f.id]?.results?.lsv);}
function payload(){const files=state.files.filter(f=>!f.deletedAt),ids=new Set(files.map(f=>f.id));return {format:'lsv-project',version:2,id:state.id,project:{id:state.id,name:state.name||'LSV项目',createdAt:state.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()},samples:[...new Map(files.map(f=>[f.sampleId,{id:f.sampleId,name:f.sampleName}])).values()],testGroups:[...new Map(files.map(f=>[f.testGroupId,{id:f.testGroupId,sampleId:f.sampleId,name:f.testGroup}])).values()],files:files.map(({deletedAt,...f})=>f),records:Object.fromEntries(Object.entries(state.records).filter(([fileId])=>ids.has(fileId))),eis:state.eis.filter(e=>ids.has(e.fileId)),settings:{reaction:state.reaction,targetCurrentsMa:[10,100,1000],currentTargetBasis:'absolute-current',equilibriumPotentialV_RHE:state.equilibriumPotentialV_RHE,overpotentialFormula:'abs(E_at_target_current - equilibriumPotential)'}};}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function saveProject(){state.id=state.id||uid('project');const data=portableSnapshot(payload()),base=(state.name||'LSV项目').replace(/[\\/:*?"<>|]/g,'_');download(new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),`${base}_${dateStamp()}.lsvproj`);state.files=state.files.filter(f=>!f.deletedAt);const keep=new Set(state.files.map(f=>f.id));state.records=Object.fromEntries(Object.entries(state.records).filter(([key])=>keep.has(key)));state.eis=state.eis.filter(e=>keep.has(e.fileId));changed();status(`项目已另存为 ${base}_${dateStamp()}.lsvproj；本机项目也已自动保存。`);renderProject();}
function migrateFiles(files){const samples=new Map(),groups=new Map();return files.map(file=>{const sampleName=file.sampleName||'未分组',sampleId=file.sampleId||samples.get(sampleName)||uid('sample');samples.set(sampleName,sampleId);const testGroup=file.testGroup||testGroupFromName(file.originalName),groupKey=`${sampleId}\u0000${testGroup}`,testGroupId=file.testGroupId||groups.get(groupKey)||uid('test-group');groups.set(groupKey,testGroupId);return {...file,sampleId,sampleName,testGroup,testGroupId,state:file.state||(file.kind==='lsv'?'raw':'attached'),deletedAt:null};});}
function loadProject(project,file){if(!project||project.format!=='lsv-project'||![1,2].includes(project.version)||!Array.isArray(project.files)||!project.records)throw Error('项目格式不正确或版本不兼容。');state.id=project.id||project.project?.id||null;state.name=project.project?.name||file?.name?.replace(/\.lsvproj$/i,'')||'LSV项目';state.createdAt=project.project?.createdAt||new Date().toISOString();state.files=migrateFiles(project.files);state.records=project.records||{};state.eis=project.eis||[];state.reaction=project.settings?.reaction||'HER';state.equilibriumPotentialV_RHE=project.settings?.equilibriumPotentialV_RHE??0;renderProject();status(`已打开 ${state.name}，共 ${state.files.length} 个文件。`);changed();showPage('home');}
function setupProjectLsvContext(file,record){const associated=state.files.filter(x=>x.kind==='eis'&&x.sampleId===file.sampleId&&x.testGroupId===file.testGroupId).map(x=>({file:x,result:state.eis.find(item=>item.fileId===x.id)})).filter(x=>Number.isFinite(x.result?.selectedResistance?.rs));const prior=record?.sourceEis?.fileId;state.currentEisSourceId=associated.some(x=>x.file.id===prior)?prior:(associated.length===1?associated[0].file.id:null);$('lsv-project-context').innerHTML=`<strong>项目处理 · ${esc(file.sampleName)} / ${esc(file.testGroup)} / ${esc(file.originalName)}</strong><div class="project-eis-source"><label for="project-eis-source">同测试组 EIS 来源</label><select id="project-eis-source"><option value="">手动填写 Rs</option>${associated.map(x=>`<option value="${esc(x.file.id)}" ${x.file.id===state.currentEisSourceId?'selected':''}>${esc(x.file.originalName)} · Rs ${esc(x.result.selectedResistance.rs)} Ω</option>`).join('')}</select><button id="project-fill-rs" type="button" class="secondary" ${associated.length?'':'disabled'}>填入 Rs</button></div>`;if(associated.length===1&&(!record?.parameters||!Number.isFinite(record.parameters.resistance)))$('resistance').value=associated[0].result.selectedResistance.rs;const select=$('project-eis-source');select.onchange=()=>{state.currentEisSourceId=select.value||null;};$('project-fill-rs').onclick=()=>{const item=associated.find(x=>x.file.id===select.value);if(!item)return;$('resistance').value=item.result.selectedResistance.rs;$('rs-source').textContent=`Rs 已从 ${item.file.originalName} 填入（${item.result.selectedResistance.rs} Ω）；请核对后处理。`;};$('rs-source').textContent=associated.length===1?'已发现同测试组 EIS，可核对来源并填入 Rs。':associated.length>1?'同组有多份已分析 EIS，请选择来源后填入 Rs。':'同测试组还没有已保存的 EIS 结果，可手动填写 Rs。';}
function openProjectFile(fileId){const f=state.files.find(x=>x.id===fileId);if(!f)return;activeMode='project';window.__lsvProjectMode=true;if(f.kind==='lsv'){state.currentFileId=f.id;const record=state.records[fileId];if(record?.parameters)for(const [key,value] of Object.entries({voltage:record.parameters.voltage,area:record.parameters.area,resistance:record.parameters.resistance}))$(key).value=value;$('lsv-upload-card').hidden=true;setupProjectLsvContext(f,record);moveLsvWorkspace('project-lsv-page');window.dispatchEvent(new CustomEvent('lsv-project-select',{detail:{file:f,record}}));showPage('projectLsv');}else if(f.kind==='eis'){state.currentEisFileId=f.id;const snapshot=state.eis.find(x=>x.fileId===fileId);showPage('eis');window.dispatchEvent(new CustomEvent('lsv-project-open-eis',{detail:{file:f,snapshot:snapshot?structuredClone(snapshot):null}}));}}
function computeTargets(data,area){return [10,100,1000].map(target=>{const density=target/area;let potential=null;for(let i=0;i<data.length-1;i++){const a=data[i],b=data[i+1],x=Math.abs(a.e),y=Math.abs(b.e);if((density-x)*(density-y)<=0&&x!==y){const t=(density-x)/(y-x);potential=a.f+t*(b.f-a.f);break;}}return {targetCurrent:target,currentUnit:'mA',targetCurrentDensity:density,currentDensityUnit:'mA/cm^2',potentialAtTargetCurrent:potential,voltageReference:'V vs. RHE',equilibriumPotentialV_RHE:0,overpotential:potential===null?null:Math.abs(potential),voltageUnit:'V',status:potential===null?'outside-data-range':'calculated'};});}
function addProjectFile(candidate,kind=candidate.kind){const sampleName=candidate.sampleName||state.name||'未分组',testGroup=candidate.testGroup||testGroupFromName(candidate.file.name);let sample=state.files.find(f=>f.sampleName===sampleName);if(!sample)sample={sampleId:uid('sample')};let group=state.files.find(f=>f.sampleId===sample.sampleId&&f.testGroup===testGroup);const f={id:uid('file'),sampleId:sample.sampleId,sampleName,testGroupId:group?.testGroupId||uid('test-group'),testGroup,originalName:candidate.file.name,relativePath:candidate.relativePath,kind,classification:kind==='lsv'?'raw':kind,state:kind==='raw-lsv'||kind==='lsv'?'raw':kind==='eis'?'unanalysed':kind==='processed'?'processed':'attached',testLabel:candidate.file.name.replace(/\.[^.]+$/,''),selected:kind==='lsv',importedAt:new Date().toISOString(),...(candidate.text&&kind!=='lsv'?{rawText:candidate.text}:{})};state.files.push(f);return f;}
async function importFiles(files){const eligible=[...files].filter(f=>/\.(txt|csv)$/i.test(f.name));if(!eligible.length){importStatus('没有找到 TXT / CSV 文件。');return;}let added=0,skipped=0,failed=0;
 for(const file of eligible){const path=relativePath(file);if(duplicatePath(path)){skipped++;continue;}try{if(file.size>20*1024*1024)throw Error('单文件超过 20 MB');const text=await file.text(),kind=classify(file,text);if(!state.name){state.name=(file.webkitRelativePath||file.name).split(/[\\/]/)[0].replace(/\.[^.]+$/,'')||'LSV项目';state.createdAt=new Date().toISOString();}const candidate={id:uid('import'),file,text,relativePath:path,kind,sampleName:sampleFromPath(path),testGroup:testGroupFromName(file.name),selected:true,rows:null};if(kind==='raw-lsv')candidate.rows=parse(text);state.candidates.push(candidate);added++;}catch{failed++;}}
 renderCandidates();importStatus(`识别完成：新增 ${added} 个文件${skipped?`，跳过重复路径 ${skipped} 个`:''}${failed?`，读取失败 ${failed} 个`:''}。请核对样品和测试组后加入项目。`);}
function exportOrigin(){const selected=state.files.filter(f=>!f.deletedAt&&f.kind==='lsv'&&f.selected!==false&&state.records[f.id]?.results?.lsv);if(!selected.length)return;const columns=[];for(const f of selected){const rows=state.records[f.id].results.lsv;columns.push({name:`${f.sampleName} ${f.testLabel} Potential`,unit:'V vs. RHE',comment:`${f.sampleName} / ${f.testLabel}`,values:rows.map(r=>r.f)},{name:`${f.sampleName} ${f.testLabel} Current density`,unit:'mA cm⁻²',comment:`${f.sampleName} / ${f.testLabel}`,values:rows.map(r=>r.e)});}const lines=[['Long Name',...columns.map(c=>c.name)],['Units',...columns.map(c=>c.unit)],['Comments',...columns.map(c=>c.comment)]];for(let i=0,n=Math.max(...columns.map(c=>c.values.length));i<n;i++)lines.push(columns.map(c=>c.values[i]===undefined?'':numberText(c.values[i])));download(new Blob(['\uFEFF'+lines.map(row=>row.join('\t')).join('\r\n')+'\r\n'],{type:'text/tab-separated-values;charset=utf-8'}),`${(state.name||'LSV项目')}_Origin_${dateStamp()}.txt`);}
function exportSummary(){const rows=[['样品','测试','类型','Rs (Ω)','Rct (Ω)','E@10mA (V vs RHE)','ηHER@10mA (V)','状态','E@100mA (V vs RHE)','ηHER@100mA (V)','状态','E@1000mA (V vs RHE)','ηHER@1000mA (V)','状态']];for(const f of state.files.filter(x=>!x.deletedAt)){const rec=state.records[f.id],eis=state.eis.find(x=>x.fileId===f.id),op=rec?.results?.overpotentials||[];if(f.kind==='lsv')rows.push([f.sampleName,f.testLabel,'LSV',rec?.parameters?.resistance??'','',... [10,100,1000].flatMap(t=>{const x=op.find(y=>y.targetCurrent===t);return [x?.potentialAtTargetCurrent??'',x?.overpotential??'',x?.status||'未处理'];})]);else if(f.kind==='eis')rows.push([f.sampleName,f.testLabel,'EIS',eis?.selectedResistance?.rs??'',eis?.selectedResistance?.rct??'','','','','','','','','','']);}const csv=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n')+'\r\n';download(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}),`${state.name||'LSV项目'}_汇总_${dateStamp()}.csv`);}
function addAttachments(){const chosen=state.candidates.filter(c=>c.selected);for(const c of chosen){const kind=c.kind==='raw-lsv'?'lsv':c.kind==='unknown'?'unknown':c.kind;const f=addProjectFile(c,kind);if(kind==='lsv'){state.records[f.id]={parameters:null,rawData:{columns:['potential_V','current_A'],rows:c.rows},results:null};}if(kind==='eis')state.eis.push({fileId:f.id,filename:f.originalName,rows:[],points:[],left:null,right:null,selectedResistance:{rs:null,total:null,rct:null}});state.candidates=state.candidates.filter(x=>x.id!==c.id);}renderCandidates();renderProject();changed();status(`已将 ${chosen.length} 个文件及其样品/测试组关联加入项目。`);}

$('nav-home').onclick=()=>showPage('home');$('nav-import').onclick=()=>showPage('import');$('nav-lsv').onclick=()=>{activeMode='standalone';state.currentFileId=null;window.__lsvProjectMode=false;moveLsvWorkspace('lsv-page');$('lsv-upload-card').hidden=false;showPage('lsv');};$('home-import').onclick=$('home-open-import').onclick=()=>showPage('import');$('import-back-home').onclick=()=>showPage('home');
 $('import-files').onclick=()=>$('import-files-input').click();$('import-files-input').onchange=e=>{importFiles(e.target.files);e.target.value='';};$('import-folder').onclick=()=>$('import-folder-input').click();$('import-folder-input').onchange=e=>{importFiles(e.target.files);e.target.value='';};$('add-attachments').onclick=addAttachments;
for(const id of ['raw-select-all','raw-select-all-bottom'])$(id).onchange=e=>{state.candidates.filter(c=>c.kind==='raw-lsv').forEach(c=>c.selected=e.target.checked);renderCandidates();};
$('project-open').onclick=()=>$('project-open-input').click();$('project-open-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>250*1024*1024)throw Error('项目文件过大。');loadProject(JSON.parse(await file.text()),file);}catch(err){status(`打开失败：${err.message}`);}};$('project-save').onclick=saveProject;$('project-origin').onclick=exportOrigin;$('project-summary').onclick=exportSummary;
window.addEventListener('lsv-project-eis-state',e=>{const {fileId,snapshot}=e.detail||{};if(!fileId)return;const file=state.files.find(f=>f.id===fileId);if(!file)return;let item=state.eis.find(x=>x.fileId===fileId);if(!item){item={fileId};state.eis.push(item);}Object.assign(item,snapshot);file.eisResult=snapshot?.selectedResistance?.rs!==null&&snapshot?.selectedResistance?.rs!==undefined;file.state=file.eisResult?'analysed':'unanalysed';renderProject();changed();});
window.addEventListener('lsv-project-current-eis',e=>{const id=state.currentEisFileId;if(id)window.dispatchEvent(new CustomEvent('lsv-project-eis-state',{detail:{fileId:id,snapshot:e.detail}}));});
window.addEventListener('lsv-project-select',e=>{const {file,record}=e.detail;window.dispatchEvent(new CustomEvent('lsv-project-load-lsv',{detail:{file,rows:record?.rawData?.rows||null,record}}));});
window.addEventListener('lsv-lsv-processed',e=>{const {rows,parameters,results}=e.detail||{},id=state.currentFileId;if(activeMode!=='project'||!id)return;const f=state.files.find(x=>x.id===id),candidate=state.currentEisSourceId&&state.eis.find(x=>x.fileId===state.currentEisSourceId),source=candidate&&Number(parameters.resistance)===Number(candidate.selectedResistance?.rs)?candidate:null;state.records[id]={parameters,rawData:{columns:['potential_V','current_A'],rows},results:{...results,overpotentials:computeTargets(results.lsv,parameters.area)},sourceEis:source?{fileId:source.fileId,rs:source.selectedResistance.rs}:null};if(f)f.state='processed';renderProject();changed();});
function saveStandaloneProject(includeRaw){const data=pendingStandalone;if(!data?.results)return;pendingStandalone=null;$('standalone-save-dialog').close();const name=data.filename||'LSV_result.txt';if(!state.name){state.name='LSV项目';state.createdAt=new Date().toISOString();}const candidate={file:{name},relativePath:name,sampleName:'未分组',testGroup:testGroupFromName(name),text:includeRaw?data.rawText:null};const f=addProjectFile(candidate,'lsv');f.state=includeRaw?'processed':'result-only';state.records[f.id]={parameters:data.parameters,rawData:includeRaw?{columns:['potential_V','current_A'],rows:data.rows}:null,results:{...data.results,overpotentials:computeTargets(data.results.lsv,data.parameters.area)},sourceEis:null};state.currentFileId=null;renderProject();changed();status(includeRaw?'原始数据和处理结果已保存到项目。':'处理结果已保存到项目；没有原始数据，无法从项目重新处理。');showPage('home');}
window.addEventListener('lsv-save-standalone',e=>{pendingStandalone=e.detail||null;if(pendingStandalone?.results)$('standalone-save-dialog').showModal();});
$('save-standalone-with-raw').onclick=()=>saveStandaloneProject(true);$('save-standalone-result-only').onclick=()=>saveStandaloneProject(false);$('cancel-standalone-save').onclick=()=>{$('standalone-save-dialog').close();pendingStandalone=null;};
window.addEventListener('lsv-file-loaded',()=>{if(activeMode==='project')return;state.currentFileId=null;window.__lsvProjectMode=false;});
window.addEventListener('app-page',e=>{if(e.detail==='lsv'){if(activeMode==='project')showPage('projectLsv');else{moveLsvWorkspace('lsv-page');state.currentFileId=null;window.__lsvProjectMode=false;$('lsv-upload-card').hidden=false;showPage('lsv');}}else showPage(e.detail);});
status('正在检查本机项目…');renderCandidates();showPage('home');
openDb().then(db=>new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readonly'),req=tx.objectStore(DB_STORE).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error);})).then(projects=>{if(!state.files.length&&projects.length){const latest=projects.sort((a,b)=>(b.project?.updatedAt||'').localeCompare(a.project?.updatedAt||''))[0];loadProject(latest,{name:`${latest.project?.name||'LSV项目'}.lsvproj`});$('project-save-state').textContent='已从本机自动恢复';}else{$('project-save-state').textContent=state.files.length?'项目已载入本机工作区':'暂无本机项目';if(!state.files.length)status('尚无项目数据。打开已有项目，或进入“导入与批处理”开始整理实验文件。');}}).catch(error=>{$('project-save-state').textContent=`本机自动保存不可用：${error.message}`;status('尚无项目数据。打开已有项目，或进入“导入与批处理”开始整理实验文件。');});
